export function careerDenominator(name:string,seasons:readonly NcaaSeason[]):1|2|3|4 {
 if (!ACTIVE_CAREERS[name]) return ELIGIBILITY_SEASONS[name] ?? 4;
 if (!seasons.length) throw new Error('Active career needs completed-season evidence');
 return Math.min(4,seasons.length) as 1|2|3|4;
}
export function scoreKnownCareer(name:string,seasons:readonly NcaaSeason[]):CareerScore {
 const career=scoreCareer(seasons,careerDenominator(name,seasons));
 if(ACTIVE_CAREERS[name]) career.activeThrough=ACTIVE_CAREERS[name].throughYear;
 return career;
}
